// 已签者与当面接收者分别记得自己的原件；principal不因授权代理自动知道远方新邀请或Task受领。
#include "political_governance_agency_intent_access.hpp"
#include "political_governance_agency_authored.hpp"
#include "resident/kernel/governance_integration.hpp"
#include "resident/kernel/command_types.hpp"
namespace hanmo::resident {namespace {
bool same(const PoliticalGovernanceAgencyOffer& o,const PoliticalGovernanceAgencyIntent& i){return o.policy_id==i.agency_policy_id&&o.issuer_actor_id==i.principal_actor_id&&o.delegate_actor_id==i.delegate_actor_id;}
// 只取已验Common真正第一份委任；后发手工来源不会恢复旧有限意图。
const PoliticalGovernanceAgencyOffer* first(const PoliticalGovernanceAgencyContext& x,const PoliticalGovernanceAgencyIntent& i){for(const auto& h:x.common.state().facts.rows()){const auto* o=x.state.offers.find(h.first);if(o&&same(*o,i))return o;}return nullptr;}
}
PoliticalGovernanceAgencyIntentAccess::PoliticalGovernanceAgencyIntentAccess(const PoliticalGovernanceAgencyBusinessContext& b,const GovernanceReadContext& g,StableId policy):business_(b),governance_(g),tasks_(g.common,g.tasks,g.governance_tasks),selected_policy_(std::move(policy)){}
Outcome<PoliticalGovernanceAgencyKnownIntent> PoliticalGovernanceAgencyIntentAccess::agency_intent_known(const StableId& actor,const PoliticalGovernanceAgencyIntent& i)const{
 const auto& x=business_.rules;if(&governance_.common!=&x.common||&governance_.governance!=&x.governance||&governance_.politics!=&x.politics||&governance_.organization!=&x.organizations)return {false,{},common_failure("GovernanceAgencyIntentCandidateMismatch",i.id).error};if(x.state.version!=2||!x.intents||!x.intents->intents.find(i.id))return {false,{},common_failure("GovernanceAgencyIntentVersionPairRequired",i.id).error};const auto& actual=*x.intents->intents.find(i.id);if(std::tie(actual.id,actual.agency_policy_id,actual.principal_actor_id,actual.delegate_actor_id,actual.executor_actor_id,actual.principal_director_policy_id,actual.delegate_director_policy_id,actual.executor_director_policy_id,actual.delegate_accepts,actual.executor_accepts)!=std::tie(i.id,i.agency_policy_id,i.principal_actor_id,i.delegate_actor_id,i.executor_actor_id,i.principal_director_policy_id,i.delegate_director_policy_id,i.executor_director_policy_id,i.delegate_accepts,i.executor_accepts))return {false,{},common_failure("GovernanceAgencyIntentImmutableMismatch",i.id).error};const bool principal=actor==i.principal_actor_id,delegate=actor==i.delegate_actor_id,executor=actor==i.executor_actor_id;if(!principal&&!delegate&&!executor)return {false,{},common_failure("GovernanceAgencyIntentObserverMismatch",actor).error};auto valid=validate_political_governance_agencies(business_);if(!valid.ok)return {false,{},valid.error};PoliticalGovernanceAgencyKnownIntent out;out.identity=x.common.state().identity;out.observer_actor_id=actor;out.intent_id=i.id;const auto* offer=first(x,i);if(!offer)return {true,std::move(out),{}};
 if(principal||delegate){out.known_offer_fact_id=offer->id;out.offer_response_before_tick=offer->response_before_tick;out.mandate_valid_through_tick=offer->valid_through_tick;}if(principal)return {true,std::move(out),{}};
 if(delegate){for(const auto& h:x.common.state().facts.rows())if(const auto* a=x.state.answers.find(h.first);a&&a->offer_fact_id==offer->id){out.own_answer_fact_id=a->id;out.own_answer_accepts=a->accept;break;}}
 for(const auto& h:x.common.state().facts.rows()){const auto* issue=x.state.issues.find(h.first);if(!issue||issue->offer_fact_id!=offer->id||issue->delegate_actor_id!=i.delegate_actor_id||issue->executor_actor_id!=i.executor_actor_id)continue;
  if(delegate){out.own_issue_fact_id=issue->id;break;}
  const auto* authority=x.governance.authorities.find(issue->authority_fact_id);if(!authority||authority->executor_actor_id!=actor)return {false,{},common_failure("GovernanceAgencyIntentKnownAuthorityMismatch",issue->id).error};out.known_authority_fact_id=authority->id;out.authority_offer_expires_tick=authority->offer_expires_tick;
  auto accepted=tasks_.governance_task_for_authority(authority->id);if(!accepted.ok)return {false,{},accepted.error};if(accepted.value){const auto& a=accepted.value->acceptance;if(a.executor_actor_id!=actor||a.authority_source_fact_id!=authority->id)return {false,{},common_failure("GovernanceAgencyIntentKnownAcceptanceMismatch",authority->id).error};out.own_task_acceptance_fact_id=a.fact_id;}break;
 }
 return {true,std::move(out),{}};
}
// 本方法再次检查本人真实地点，然后进入原完整预览；远方producer不会调用它。
Outcome<std::shared_ptr<const CommandPayload>> PoliticalGovernanceAgencyIntentAccess::preview_agency_intent_local(const StableId& actor,const PoliticalGovernanceAgencyIntent& i,const PoliticalGovernanceAgencyKnownIntent& known)const{
 const auto& x=business_.rules;auto fresh=agency_intent_known(actor,i);if(!fresh.ok)return {false,{},fresh.error};const auto& k=fresh.value;if(k.known_offer_fact_id!=known.known_offer_fact_id||k.own_answer_fact_id!=known.own_answer_fact_id||k.known_authority_fact_id!=known.known_authority_fact_id)return {false,{},common_failure("GovernanceAgencyIntentKnowledgeChanged",i.id).error};const auto* p=x.catalog.policies.find(i.agency_policy_id);const auto* j=p?x.politics.jurisdictions.find(p->jurisdiction_id):nullptr;const auto* a=x.common.actor(actor);const auto* at=a?std::get_if<SettlementLocation>(&a->location):nullptr;if(!j||!at||at->place_id!=j->seat_place_id)return {false,{},common_failure("GovernanceAgencyIntentLocalPreviewRequired",i.id).error};
 if(actor==i.executor_actor_id){if(!i.executor_accepts||selected_policy_!=i.executor_director_policy_id||k.known_authority_fact_id.empty())return {false,{},common_failure("GovernanceAgencyIntentAwaitingOriginalInvitation",i.id).error};GovernanceCommand command=GovernanceAcceptCommand{k.known_authority_fact_id,x.common.revision()};auto q=preview_governance_business(governance_,actor,command);if(!q.ok)return {false,{},q.error};return {true,std::make_shared<const CommandPayload>(CommandPayload{"governance_accept",std::move(command)}),{}};}
 PoliticalGovernanceAgencyAuthoredOrigin origin;origin.intent_id=i.id;origin.director_policy_id=selected_policy_;origin.actor_id=actor;PoliticalGovernanceAgencyCommand command;
 if(actor==i.principal_actor_id){const auto* office=x.organizations.offices.find(p->office_id);if(!office||!k.known_offer_fact_id.empty())return {false,{},common_failure("GovernanceAgencyIntentOfferConsumed",i.id).error};origin.step=PoliticalGovernanceAgencyAuthoredStep::offer;command=PoliticalOfferGovernanceAgency{{office->organization_id,office->id,office->epoch,actor},i.agency_policy_id,i.delegate_actor_id,j->revision};}
 else if(actor==i.delegate_actor_id){if(k.known_offer_fact_id.empty())return {false,{},common_failure("GovernanceAgencyIntentAwaitingOriginalOffer",i.id).error};if(k.own_answer_fact_id.empty()){origin.step=PoliticalGovernanceAgencyAuthoredStep::answer;command=PoliticalAnswerGovernanceAgency{k.known_offer_fact_id,i.delegate_accepts};}else{if(!k.own_answer_accepts||!k.own_issue_fact_id.empty())return {false,{},common_failure("GovernanceAgencyIntentOfferConsumed",i.id).error};origin.step=PoliticalGovernanceAgencyAuthoredStep::issue;command=PoliticalIssueAgencyGovernance{k.known_offer_fact_id,k.own_answer_fact_id,i.executor_actor_id};}}
 else return {false,{},common_failure("GovernanceAgencyIntentObserverMismatch",actor).error};
 auto rules=x;rules.authored_command=&origin;PoliticalGovernanceAgencyBusinessContext local{rules,business_.relief_catalog,business_.result_match};auto q=preview_political_governance_agency_business(local,actor,command);if(!q.ok)return {false,{},q.error};return {true,std::make_shared<const CommandPayload>(CommandPayload{political_governance_agency_command_kind(command),AuthoredGovernanceAgencyCommand{origin,std::move(command)}}),{}};
}
// 仅原本人来源能完成自身意图，Task后来取消仍保留其真实接受，后来新源不能补旧复评。
Status PoliticalGovernanceAgencyIntentAccess::completed_before_review(const PoliticalGovernanceAgencyIntent& i,const StableId& actor,const StableId& fact,Integer tick)const{const auto& x=business_.rules;if(tick<0||tick>x.common.tick()||(actor==i.executor_actor_id&&!i.executor_accepts))return common_failure("GovernanceAgencyIntentReviewBoundaryMismatch",fact);auto known=agency_intent_known(actor,i);if(!known.ok)return {false,{},known.error};Integer source_tick=-1;
 if(actor==i.principal_actor_id&&known.value.known_offer_fact_id==fact){const auto* o=x.state.offers.find(fact);if(o)source_tick=o->tick;}
 else if(actor==i.delegate_actor_id){if(known.value.own_issue_fact_id==fact){const auto* v=x.state.issues.find(fact);if(v)source_tick=v->tick;}else if(known.value.own_answer_fact_id==fact&&!known.value.own_answer_accepts){const auto* v=x.state.answers.find(fact);if(v)source_tick=v->tick;}}
 else if(actor==i.executor_actor_id&&known.value.own_task_acceptance_fact_id==fact){auto a=tasks_.governance_task_for_authority(known.value.known_authority_fact_id);if(!a.ok)return {false,{},a.error};if(a.value)source_tick=a.value->acceptance.accepted_tick;}
 return source_tick>=0&&source_tick<=tick?common_success():common_failure("GovernanceAgencyIntentCompletedSourceMismatch",fact);
}
}
